{"output": "from math import inf


def _components(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                rr, cc = stack.pop()
                cells.add((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            result.append((color, cells))
    return bg, result


def _l_guides(cells):
    """Return exact L-shaped components as (elbow, open-quadrant-signs)."""
    guides = []
    for r0, c0 in cells:
        for vr in (-1, 1):
            for hc in (-1, 1):
                vertical = {(r, c0) for r, c in cells if c == c0 and (r-r0)*vr >= 0}
                horizontal = {(r0, c) for r, c in cells if r == r0 and (c-c0)*hc >= 0}
                union = vertical | horizontal
                if union != cells or len(vertical) < 3 or len(horizontal) < 3:
                    continue
                # The empty diagonal quadrant is opposite the two occupied arms.
                guides.append((r0, c0, -vr, -hc))
    return guides


def transform(grid):
    """Recolor the nearest object in the empty quadrant indicated by an L guide."""
    bg, comps = _components(grid)
    guides = []
    for color, cells in comps:
        for r0, c0, qrow, qcol in _l_guides(cells):
            guides.append((color, cells, r0, c0, qrow, qcol))
    if not guides:
        return [row[:] for row in grid]

    # The longest scaffold is the most reliable directional guide when incidental Ls occur.
    guide_color, guide_cells, r0, c0, qrow, qcol = max(
        guides, key=lambda item: len(item[1])
    )
    candidates = []
    for color, cells in comps:
        if cells == guide_cells:
            continue
        cr = sum(r for r, _ in cells) / len(cells)
        cc = sum(c for _, c in cells) / len(cells)
        d = min((gr-r)**2 + (gc-c)**2 for gr, gc in guide_cells for r, c in cells)
        candidates.append((d, color, cells))
    if not candidates:
        return [row[:] for row in grid]

    _, _, target = max(candidates, key=lambda item: item[0])
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = guide_color
    return out


if __name__ == '__main__':
    pass", "exit_code": 0, "error": null}

