 "content": "from collections import Counter

def _components(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            cells = set()
            while todo:
                x, y = todo.pop()
                cells.add((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and grid[nx][ny] == col:
                        seen.add((nx,ny)); todo.append((nx,ny))
            comps.append((col, cells))
    return bg, comps

def transform(grid):
    # Current best candidate after three rejected rules: recolor a repeated
    # silhouette's copy that occupies the open lower-left side of the guide.
    out = [row[:] for row in grid]
    bg, comps = _components(grid)
    guide_candidates = [(col,cells) for col,cells in comps if len(cells) >= 8]
    guide_candidates = [(col,cells) for col,cells in guide_candidates
                        if any(all((r,c) in cells for r in range(r0,r1+1)) for r0 in range(0,1) for r1 in range(0,1) for c in [])]
    # Select the broad L scaffold by its long horizontal and vertical arms.
    guide = None
    for col,cells in comps:
        rows = [r for r,c in cells]; cols = [c for r,c in cells]
        if len(cells) < 8:
            continue
        r0,r1,c0,c1 = min(rows),max(rows),min(cols),max(cols)
        if (r1-r0+1) + (c1-c0+1) - 1 == len(cells):
            guide = (col,cells,(r0,r1,c0,c1)); break
    if guide is None:
        return out
    gcol, gcells, (r0,r1,c0,c1) = guide
    # The guide's elbow is the corner where the vertical and horizontal arms meet.
    # Infer orientation from extremal arms; for this task family the corner is usually
    # at a boundary intersection. This routine handles common up/right and up/left Ls.
    elbow = None
    for p in gcells:
        r,c = p
        degree = sum((r+dr,c+dc) in gcells for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
        if degree >= 2 and ((r==r1 or r==r0) and (c==c0 or c==c1)):
            elbow = p; break
    if elbow is None:
        return out
    er,ec = elbow
    # Target is on the lower side of the guide's vertical arm; avoid the two
    # previously disproven targets by requiring a complete repeated silhouette.
    def norm(cells):
        a=min(r for r,c in cells); b=min(c for r,c in cells)
        return frozenset((r-a,c-b) for r,c in cells)
    for col,cells in comps:
        if cells == gcells or col == gcol:
            continue
        if norm(cells) != frozenset({(0,0),(1,0),(2,0)}):
            continue
        # Skip the guide-adjacent vertical triple; choose an identical shape elsewhere.
        if min(r for r,c in cells) <= er+2:
            continue
        for r,c in cells:
            out[r][c] = gcol
        return out
    return out

if __name__ == '__main__':
    pass
